-- 24: Importa as NF-e recebidas da CGH (empresa 57, loja 'teste') com emissão de 01/08/2026 até 20/11/2026, extraídas do Everest
--     (DFI > Monitor de DANFEs Recebidas, aba Itens) em 22/11/2026. 116 notas e 606 linhas de NF-e. A 184284 já existia e foi pulada.
-- Entram como PENDENTES (status pending, origin everest): não mexem no estoque. Itens em invoice_nfe_items; item_id = nosso item quando o código do Everest existe em items.
-- Fornecedor pelo CNPJ (suppliers.tax_id). Não duplica: pula a nota se a chave de acesso já existir na loja.
-- Arquivo bruto: Documents/MFT/dados/everest_danfes_itens_57_2026-08_2026-11.txt
-- Número de nota só é único POR FORNECEDOR (e série): troca a unique (store_id, invoice_number) por (store_id, supplier_id, invoice_number, series).
--   Motivo: Eurofoods matriz e filial emitiram a nota 6378 para a CGH. Reversão da constraint: drop invoices_store_supplier_number_key; add unique (store_id, invoice_number).
-- Reversão: delete from public.invoices where store_id='teste' and origin='everest' and notes like 'Importada do Everest em lote 22/11/2026%' and status='pending';
begin;
alter table public.invoices drop constraint if exists invoices_store_id_invoice_number_key;
alter table public.invoices drop constraint if exists invoices_store_supplier_number_key;
alter table public.invoices add constraint invoices_store_supplier_number_key unique nulls not distinct (store_id, supplier_id, invoice_number, series);
create temp table _nf (num text, serie text, cnpj text, emissao date, entrada date, chave text, total numeric) on commit drop;
create temp table _it (chave text, seq int, c text, d text, u text, p text, qe numeric, q numeric, vu numeric, vd numeric, vt numeric, cfop text, ec text, es numeric) on commit drop;

select 'teste',n.num,n.serie,(select s.id from public.suppliers s where s.tax_id=n.cnpj limit 1),n.emissao,n.entrada,n.chave,'pending',n.total,'everest',
       'Importada do Everest em lote 22/11/2026 (Monitor de DANFEs Recebidas). Itens da NF-e em invoice_nfe_items.'
from _nf n where not exists (select 1 from public.invoices i where i.store_id='teste' and i.access_key=n.chave);

select i.id,'teste',t.seq,t.c,t.d,t.u,t.p,t.qe,t.q,t.vu,coalesce(t.vd,0),t.vt,t.cfop,t.ec,it.name,t.es,it.id
from _it t join public.invoices i on i.store_id='teste' and i.access_key=t.chave
left join public.items it on it.code=t.ec
where not exists (select 1 from public.invoice_nfe_items x where x.invoice_id=i.id and x.seq=t.seq);

select count(*) filter (where origin='everest') notas_everest, count(*) filter (where supplier_id is null) sem_fornecedor,
       (select count(*) from public.invoice_nfe_items where store_id='teste') linhas_nfe,
       (select count(*) from public.invoice_nfe_items where store_id='teste' and item_id is not null) com_item_everest
from public.invoices where store_id='teste';
commit;
